window.TIDE_LOCAL_DATA={"files":{"index.wasm":{"size":39514754,"mime":"application/wasm","gzip":""},"index.pck":{"size":14784476,"mime":"application/octet-stream","gzip":""}},"worklets":{"index.audio.worklet.js":"/**************************************************************************/\n/*  audio.worklet.js                                                      */\n/**************************************************************************/\n/*                         This file is part of:                          */\n/*                             GODOT ENGINE                               */\n/*                        https://godotengine.org                         */\n/**************************************************************************/\n/* Copyright (c) 2014-present Godot Engine contributors (see AUTHORS.md). */\n/* Copyright (c) 2007-2014 Juan Linietsky, Ariel Manzur.                  */\n/*                                                                        */\n/* Permission is hereby granted, free of charge, to any person obtaining  */\n/* a copy of this software and associated documentation files (the        */\n/* \"Software\"), to deal in the Software without restriction, including    */\n/* without limitation the rights to use, copy, modify, merge, publish,    */\n/* distribute, sublicense, and/or sell copies of the Software, and to     */\n/* permit persons to whom the Software is furnished to do so, subject to  */\n/* the following conditions:                                              */\n/*                                                                        */\n/* The above copyright notice and this permission notice shall be         */\n/* included in all copies or substantial portions of the Software.        */\n/*                                                                        */\n/* THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND,        */\n/* EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF     */\n/* MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. */\n/* IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY   */\n/* CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT,   */\n/* TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE      */\n/* SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.                 */\n/**************************************************************************/\n\nclass RingBuffer {\n\tconstructor(p_buffer, p_state, p_threads) {\n\t\tthis.buffer = p_buffer;\n\t\tthis.avail = p_state;\n\t\tthis.threads = p_threads;\n\t\tthis.rpos = 0;\n\t\tthis.wpos = 0;\n\t}\n\n\tdata_left() {\n\t\treturn this.threads ? Atomics.load(this.avail, 0) : this.avail;\n\t}\n\n\tspace_left() {\n\t\treturn this.buffer.length - this.data_left();\n\t}\n\n\tread(output) {\n\t\tconst size = this.buffer.length;\n\t\tlet from = 0;\n\t\tlet to_write = output.length;\n\t\tif (this.rpos + to_write > size) {\n\t\t\tconst high = size - this.rpos;\n\t\t\toutput.set(this.buffer.subarray(this.rpos, size));\n\t\t\tfrom = high;\n\t\t\tto_write -= high;\n\t\t\tthis.rpos = 0;\n\t\t}\n\t\tif (to_write) {\n\t\t\toutput.set(this.buffer.subarray(this.rpos, this.rpos + to_write), from);\n\t\t}\n\t\tthis.rpos += to_write;\n\t\tif (this.threads) {\n\t\t\tAtomics.add(this.avail, 0, -output.length);\n\t\t\tAtomics.notify(this.avail, 0);\n\t\t} else {\n\t\t\tthis.avail -= output.length;\n\t\t}\n\t}\n\n\twrite(p_buffer) {\n\t\tconst to_write = p_buffer.length;\n\t\tconst mw = this.buffer.length - this.wpos;\n\t\tif (mw >= to_write) {\n\t\t\tthis.buffer.set(p_buffer, this.wpos);\n\t\t\tthis.wpos += to_write;\n\t\t\tif (mw === to_write) {\n\t\t\t\tthis.wpos = 0;\n\t\t\t}\n\t\t} else {\n\t\t\tconst high = p_buffer.subarray(0, mw);\n\t\t\tconst low = p_buffer.subarray(mw);\n\t\t\tthis.buffer.set(high, this.wpos);\n\t\t\tthis.buffer.set(low);\n\t\t\tthis.wpos = low.length;\n\t\t}\n\t\tif (this.threads) {\n\t\t\tAtomics.add(this.avail, 0, to_write);\n\t\t\tAtomics.notify(this.avail, 0);\n\t\t} else {\n\t\t\tthis.avail += to_write;\n\t\t}\n\t}\n}\n\nclass GodotProcessor extends AudioWorkletProcessor {\n\tconstructor() {\n\t\tsuper();\n\t\tthis.threads = false;\n\t\tthis.running = true;\n\t\tthis.lock = null;\n\t\tthis.notifier = null;\n\t\tthis.output = null;\n\t\tthis.output_buffer = new Float32Array();\n\t\tthis.input = null;\n\t\tthis.input_buffer = new Float32Array();\n\t\tthis.port.onmessage = (event) => {\n\t\t\tconst cmd = event.data['cmd'];\n\t\t\tconst data = event.data['data'];\n\t\t\tthis.parse_message(cmd, data);\n\t\t};\n\t}\n\n\tprocess_notify() {\n\t\tif (this.notifier) {\n\t\t\tAtomics.add(this.notifier, 0, 1);\n\t\t\tAtomics.notify(this.notifier, 0);\n\t\t}\n\t}\n\n\tparse_message(p_cmd, p_data) {\n\t\tif (p_cmd === 'start' && p_data) {\n\t\t\tconst state = p_data[0];\n\t\t\tlet idx = 0;\n\t\t\tthis.threads = true;\n\t\t\tthis.lock = state.subarray(idx, ++idx);\n\t\t\tthis.notifier = state.subarray(idx, ++idx);\n\t\t\tconst avail_in = state.subarray(idx, ++idx);\n\t\t\tconst avail_out = state.subarray(idx, ++idx);\n\t\t\tthis.input = new RingBuffer(p_data[1], avail_in, true);\n\t\t\tthis.output = new RingBuffer(p_data[2], avail_out, true);\n\t\t} else if (p_cmd === 'stop') {\n\t\t\tthis.running = false;\n\t\t\tthis.output = null;\n\t\t\tthis.input = null;\n\t\t\tthis.lock = null;\n\t\t\tthis.notifier = null;\n\t\t} else if (p_cmd === 'start_nothreads') {\n\t\t\tthis.output = new RingBuffer(p_data[0], p_data[0].length, false);\n\t\t} else if (p_cmd === 'chunk') {\n\t\t\tthis.output.write(p_data);\n\t\t}\n\t}\n\n\tstatic array_has_data(arr) {\n\t\treturn arr.length && arr[0].length && arr[0][0].length;\n\t}\n\n\tprocess(inputs, outputs, parameters) {\n\t\tif (!this.running) {\n\t\t\treturn false; // Stop processing.\n\t\t}\n\t\tif (this.output === null) {\n\t\t\treturn true; // Not ready yet, keep processing.\n\t\t}\n\t\tconst process_input = GodotProcessor.array_has_data(inputs);\n\t\tif (process_input) {\n\t\t\tconst input = inputs[0];\n\t\t\tconst chunk = input[0].length * input.length;\n\t\t\tif (this.input_buffer.length !== chunk) {\n\t\t\t\tthis.input_buffer = new Float32Array(chunk);\n\t\t\t}\n\t\t\tif (!this.threads) {\n\t\t\t\tGodotProcessor.write_input(this.input_buffer, input);\n\t\t\t\tthis.port.postMessage({ 'cmd': 'input', 'data': this.input_buffer });\n\t\t\t} else if (this.input.space_left() >= chunk) {\n\t\t\t\tGodotProcessor.write_input(this.input_buffer, input);\n\t\t\t\tthis.input.write(this.input_buffer);\n\t\t\t} else {\n\t\t\t\t// this.port.postMessage('Input buffer is full! Skipping input frame.'); // Uncomment this line to debug input buffer.\n\t\t\t}\n\t\t}\n\t\tconst process_output = GodotProcessor.array_has_data(outputs);\n\t\tif (process_output) {\n\t\t\tconst output = outputs[0];\n\t\t\tconst chunk = output[0].length * output.length;\n\t\t\tif (this.output_buffer.length !== chunk) {\n\t\t\t\tthis.output_buffer = new Float32Array(chunk);\n\t\t\t}\n\t\t\tif (this.output.data_left() >= chunk) {\n\t\t\t\tthis.output.read(this.output_buffer);\n\t\t\t\tGodotProcessor.write_output(output, this.output_buffer);\n\t\t\t\tif (!this.threads) {\n\t\t\t\t\tthis.port.postMessage({ 'cmd': 'read', 'data': chunk });\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\t// this.port.postMessage('Output buffer has not enough frames! Skipping output frame.'); // Uncomment this line to debug output buffer.\n\t\t\t}\n\t\t}\n\t\tthis.process_notify();\n\t\treturn true;\n\t}\n\n\tstatic write_output(dest, source) {\n\t\tconst channels = dest.length;\n\t\tfor (let ch = 0; ch < channels; ch++) {\n\t\t\tfor (let sample = 0; sample < dest[ch].length; sample++) {\n\t\t\t\tdest[ch][sample] = source[sample * channels + ch];\n\t\t\t}\n\t\t}\n\t}\n\n\tstatic write_input(dest, source) {\n\t\tconst channels = source.length;\n\t\tfor (let ch = 0; ch < channels; ch++) {\n\t\t\tfor (let sample = 0; sample < source[ch].length; sample++) {\n\t\t\t\tdest[sample * channels + ch] = source[ch][sample];\n\t\t\t}\n\t\t}\n\t}\n}\n\nregisterProcessor('godot-processor', GodotProcessor);\n","index.audio.position.worklet.js":"/**************************************************************************/\n/*  godot.audio.position.worklet.js                                                      */\n/**************************************************************************/\n/*                         This file is part of:                          */\n/*                             GODOT ENGINE                               */\n/*                        https://godotengine.org                         */\n/**************************************************************************/\n/* Copyright (c) 2014-present Godot Engine contributors (see AUTHORS.md). */\n/* Copyright (c) 2007-2014 Juan Linietsky, Ariel Manzur.                  */\n/*                                                                        */\n/* Permission is hereby granted, free of charge, to any person obtaining  */\n/* a copy of this software and associated documentation files (the        */\n/* \"Software\"), to deal in the Software without restriction, including    */\n/* without limitation the rights to use, copy, modify, merge, publish,    */\n/* distribute, sublicense, and/or sell copies of the Software, and to     */\n/* permit persons to whom the Software is furnished to do so, subject to  */\n/* the following conditions:                                              */\n/*                                                                        */\n/* The above copyright notice and this permission notice shall be         */\n/* included in all copies or substantial portions of the Software.        */\n/*                                                                        */\n/* THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND,        */\n/* EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF     */\n/* MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. */\n/* IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY   */\n/* CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT,   */\n/* TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE      */\n/* SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.                 */\n/**************************************************************************/\n\nclass GodotPositionReportingProcessor extends AudioWorkletProcessor {\n\tstatic get parameterDescriptors() {\n\t\treturn [\n\t\t\t{\n\t\t\t\tname: 'reset',\n\t\t\t\tdefaultValue: 0,\n\t\t\t\tminValue: 0,\n\t\t\t\tmaxValue: 1,\n\t\t\t\tautomationRate: 'k-rate',\n\t\t\t},\n\t\t];\n\t}\n\n\tconstructor(...args) {\n\t\tsuper(...args);\n\t\tthis.position = 0;\n\t}\n\n\tprocess(inputs, _outputs, parameters) {\n\t\tif (parameters['reset'][0] > 0) {\n\t\t\tthis.position = 0;\n\t\t}\n\n\t\tif (inputs.length > 0) {\n\t\t\tconst input = inputs[0];\n\t\t\tif (input.length > 0) {\n\t\t\t\tthis.position += input[0].length;\n\t\t\t\tthis.port.postMessage({ type: 'position', data: this.position });\n\t\t\t}\n\t\t}\n\n\t\treturn true;\n\t}\n}\n\nregisterProcessor('godot-position-reporting-processor', GodotPositionReportingProcessor);\n"}};
